'use strict';

function reportCount() {
  return `count is ${this.count}`;
}

const counter = { count: 5 };
const other = { count: 42 };

console.log(reportCount.call(counter));
console.log(reportCount.apply(other));

const bound = reportCount.bind(counter);
console.log(bound());

try {
  reportCount();
} catch (err) {
  console.log('error:', err.constructor.name);
}
